function validate([s]) {
  if (typeof s !== 'string') return 's must be a string.';
  if (s.length < 1 || s.length > 1000) return 's has 1 to 1000 characters.';
  if (!/^[ALP]+$/.test(s)) return "s may only contain 'A', 'L' and 'P'.";
  return null;
}

