function checkRecord(s) {
  let absences = 0;
  let lateStreak = 0;
  for (const day of s) {
    if (day === 'A') {
      absences++;
      if (absences >= 2) {
        return false;
      }
    }
    if (day === 'L') {
      lateStreak++;
      if (lateStreak >= 3) {
        return false;
      }
    } else {
      lateStreak = 0;
    }
  }
  return true;
}

