function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 900 + pick(101) : 1 + pick(12);
  const letters = 'ALP';
  if (rand() < 0.5) {
    // Biased random days: lates are common so runs of three appear, absences are rare.
    let s = '';
    for (let i = 0; i < n; i++) {
      const r = rand();
      s += r < (size === 'large' ? 0.002 : 0.12) ? 'A' : r < 0.55 ? 'L' : 'P';
    }
    return [s];
  }
  // Build a record that earns the award, then sometimes break exactly one rule.
  const days = [];
  for (let i = 0; i < n; i++) {
    const run = i >= 2 && days[i - 1] === 'L' && days[i - 2] === 'L';
    days.push(run ? 'P' : letters[1 + pick(2)]);
  }
  if (rand() < 0.6) days[pick(n)] = 'A';
  const twist = pick(3);
  if (twist === 1 && n >= 2) {
    const i = pick(n);
    let j = pick(n);
    if (j === i) j = (i + 1) % n;
    days[i] = 'A';
    days[j] = 'A';
  } else if (twist === 2 && n >= 3) {
    const start = pick(n - 2);
    days[start] = days[start + 1] = days[start + 2] = 'L';
  }
  return [days.join('')];
}
